+import React, { useEffect, useState } from 'react';
+
+import { _t } from '../../../../languageHandler';
+import AccessibleButton from '../../elements/AccessibleButton';
+import Spinner from '../../elements/Spinner';
+import Heading from '../../typography/Heading';
+import { DeviceWithVerification } from './types';
+
+interface Props {
+    device: DeviceWithVerification;
+    saveDeviceName: (deviceId: string, deviceName: string) => Promise<void>;
+}
+
+export const DeviceDetailHeading: React.FC<Props> = ({ device, saveDeviceName }) => {
+    const [isEditing, setIsEditing] = useState(false);
+    const [name, setName] = useState('');
+    const [isSaving, setIsSaving] = useState(false);
+    const [error, setError] = useState<string>();
+    const [savedName, setSavedName] = useState<string>();
+    const previousName = savedName ?? device.display_name;
+
+    useEffect(() => setSavedName(undefined), [device.device_id, device.display_name]);
+
+    const onRename = (): void => {
+        setName(previousName ?? device.device_id);
+        setError(undefined);
+        setIsEditing(true);
+    };
+
+    const onCancel = (): void => {
+        setError(undefined);
+        setIsEditing(false);
+    };
+
+    const onSave = async (event: React.FormEvent): Promise<void> => {
+        event.preventDefault();
+        if (isSaving) {
+            return;
+        }
+        if (name === previousName) {
+            setIsEditing(false);
+            return;
+        }
+        setIsSaving(true);
+        setError(undefined);
+        try {
+            await saveDeviceName(device.device_id, name);
+            setSavedName(name);
+            setIsEditing(false);
+        } catch (error) {
+            setError(_t('Failed to set display name.'));
+        } finally {
+            setIsSaving(false);
+        }
+    };
+
+    if (!isEditing) {
+        return <div className='mx_DeviceDetailHeading' data-testid='device-detail-heading'>
+            <Heading size='h3'>{ previousName ?? device.device_id }</Heading>
+            <AccessibleButton kind='link_inline' onClick={onRename} data-testid='device-detail-rename'>
+                { _t('Rename') }
+            </AccessibleButton>
+        </div>;
+    }
+
+    return <form className='mx_DeviceDetailHeading' data-testid='device-detail-heading-edit' onSubmit={onSave}>
+        <label htmlFor={`device-name-${device.device_id}`}>{ _t('Session name') }</label>
+        <input
+            id={`device-name-${device.device_id}`}
+            data-testid='device-detail-name-input'
+            type='text'
+            maxLength={100}
+            value={name}
+            disabled={isSaving}
+            onChange={event => setName(event.target.value)}
+        />
+        <p>{ _t("A device's name is visible to people you communicate with.") }</p>
+        { error && <p role='alert' data-testid='device-detail-name-error'>{ error }</p> }
+        <div className='mx_DeviceDetailHeading_actions'>
+            <button type='submit' disabled={isSaving} data-testid='device-detail-name-save'>
+                { _t('Save') }
+            </button>
+            <button type='button' disabled={isSaving} onClick={onCancel} data-testid='device-detail-name-cancel'>
+                { _t('Cancel') }
+            </button>
+            { isSaving && <Spinner w={16} h={16} /> }
+        </div>
+    </form>;
+};
